#!/usr/bin/env node
// Generates <slug>-story-i18n-data.js for the 20 Rosary mystery books: window.<SLUG>_STORY_<LANG>
// globals built from the localized catalogs (content/books/<slug>/<lang>.json) with per-page
// structure (scene, image, reflection flag, evidence types and source ids) from book.json.
// All wording lives in the catalogs; the JS is a generated projection. The English globals stay
// in <slug>-story-data.js. --check: verify the generated files are up to date without writing.
import fs from 'node:fs';
import path from 'node:path';
const ROOT = path.resolve(path.dirname(new URL(import.meta.url).pathname), '../..');
const LOCALES = ['ar', 'de', 'es', 'fr', 'it', 'pl', 'pt'];
const GLOB = { ar: 'AR', de: 'DE', es: 'ES', fr: 'FR', it: 'IT', pl: 'PL', pt: 'PT' };
export const ROSARY_SLUGS = ['joyful-annunciation', 'joyful-visitation', 'joyful-nativity', 'joyful-presentation', 'joyful-finding-temple', 'luminous-baptism', 'luminous-cana', 'luminous-proclamation', 'luminous-transfiguration', 'luminous-eucharist', 'sorrowful-agony-garden', 'sorrowful-scourging', 'sorrowful-crowning-thorns', 'sorrowful-carrying-cross', 'sorrowful-crucifixion', 'glorious-resurrection', 'glorious-ascension', 'glorious-pentecost', 'glorious-assumption', 'glorious-coronation'];
const readJson = f => JSON.parse(fs.readFileSync(path.join(ROOT, f), 'utf8'));
const check = process.argv.includes('--check');
let stale = 0;
for (const slug of ROSARY_SLUGS) {
  const dir = `content/books/${slug}`;
  const book = readJson(`${dir}/book.json`);
  const assetPath = Object.fromEntries(book.assets.map(a => [a.id, './' + a.path]));
  const chunks = ['// GENERATED by scripts/books/build-rosary-i18n-data.mjs - do not edit by hand.',
    `// Agent-translated editions (review: agent-translated); EN lives in ${slug}-story-data.js.`];
  for (const loc of LOCALES) {
    const cat = readJson(`${dir}/${loc}.json`);
    if (cat.locale !== loc || cat.review !== 'agent-translated' || cat.pages.length !== book.pages.length) throw new Error(`${slug}/${loc}: catalog shape mismatch`);
    const pages = cat.pages.map((p, i) => {
      const bp = book.pages[i];
      if (p.id !== bp.id) throw new Error(`${slug}/${loc} page ${i + 1}: id order mismatch`);
      const claims = (cat.evidenceClaims || {})[p.id] || [];
      return {
        illustration: assetPath[bp.image], title: p.title, body: p.body, prayer: p.prayer, heart: p.heart,
        scene: bp.scene || 'legacy', audio: '', reflection: bp.kind === 'reflection',
        evidence: bp.evidence.map((e, j) => ({ type: e.type, claim: j < claims.length ? claims[j] : e.claim, sources: e.sources }))
      };
    });
    chunks.push(`window.${slug.toUpperCase().replace(/-/g, '_')}_STORY_${GLOB[loc]} = ${JSON.stringify(pages, null, 1)};\n`);
  }
  const file = `${slug}-story-i18n-data.js`;
  const text = chunks.join('\n');
  const current = fs.existsSync(path.join(ROOT, file)) ? fs.readFileSync(path.join(ROOT, file), 'utf8') : '';
  if (current !== text) {
    if (check) { console.error(file + ': out of date'); stale++; }
    else { fs.writeFileSync(path.join(ROOT, file), text); console.log(file + ': written'); }
  }
}
if (!stale) console.log(check ? 'rosary i18n data: up to date' : 'rosary i18n data: done');
process.exit(check && stale ? 1 : 0);
